// Guides whose screenshots haven't been shot yet (BaseLayout robots="noindex, follow"
// on the page itself — see astro.config.mjs NOINDEXED_GUIDE_ROUTES, which must be
// kept in sync with this list). Hidden from guidesBySection() so their cards don't
// appear on the /debugging, /how-to, or /resources hub pages until images are added.
// Still resolvable directly by URL and still eligible for relatedGuides() cross-links.
const PENDING_IMAGE_ROUTES = new Set<string>([]);

export function guidesBySection(section: GuideSection): GuideMeta[] {
  return GUIDES.filter((g) => g.section === section && !PENDING_IMAGE_ROUTES.has(`${g.section}/${g.slug}`));
}

export function relatedGuides(currentSlug: string, count = 3): GuideMeta[] {
  const idx = GUIDES.findIndex((g) => g.slug === currentSlug);
  const start = idx === -1 ? 0 : idx + 1;
  const out: GuideMeta[] = [];
  for (let i = 0; i < GUIDES.length && out.length < count; i++) {
    const g = GUIDES[(start + i) % GUIDES.length];
    if (g.slug !== currentSlug) out.push(g);
  }
  return out;
}
